-- Stage 10: tenant-scoped, immutable context graph and role-evaluation evidence.
CREATE TABLE IF NOT EXISTS adx_context_node (id uuid PRIMARY KEY, organization_id uuid NOT NULL, workspace_id uuid NOT NULL, node jsonb NOT NULL, node_digest text NOT NULL, repository_id text NOT NULL, kind text NOT NULL, recorded_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id,workspace_id,node_digest));
CREATE TABLE IF NOT EXISTS adx_context_edge (id uuid PRIMARY KEY, organization_id uuid NOT NULL, workspace_id uuid NOT NULL, edge jsonb NOT NULL, edge_digest text NOT NULL, recorded_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id,workspace_id,edge_digest));
CREATE TABLE IF NOT EXISTS adx_role_evaluation (id uuid PRIMARY KEY, organization_id uuid NOT NULL, workspace_id uuid NOT NULL, role_id text NOT NULL, evaluation jsonb NOT NULL, evaluation_digest text NOT NULL, recorded_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (organization_id,workspace_id,evaluation_digest));
CREATE OR REPLACE FUNCTION adx_reject_context_graph_mutation() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'ADX_IMMUTABLE_CONTEXT_GRAPH'; END; $$ LANGUAGE plpgsql;
DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['adx_context_node','adx_context_edge','adx_role_evaluation'] LOOP EXECUTE format('DROP TRIGGER IF EXISTS %I ON %I', table_name || '_immutable', table_name); EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION adx_reject_context_graph_mutation()', table_name || '_immutable', table_name); EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', table_name); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', table_name); EXECUTE format('DROP POLICY IF EXISTS %I ON %I', table_name || '_tenant_isolation', table_name); EXECUTE format('CREATE POLICY %I ON %I USING (organization_id=current_setting(''adx.organization_id'',true)::uuid AND workspace_id=current_setting(''adx.workspace_id'',true)::uuid) WITH CHECK (organization_id=current_setting(''adx.organization_id'',true)::uuid AND workspace_id=current_setting(''adx.workspace_id'',true)::uuid)', table_name || '_tenant_isolation', table_name); END LOOP; END $$;
